def min_actions_to_sort_train(n, p):
    sorted_p = sorted(p)
    index_map = {val: idx for idx, val in enumerate(sorted_p)}
    current = list(range(1, n + 1))
    actions = 0

    for i in range(n):
        while current[i] != p[i]:
            pos = index_map[p[i]]
            if pos > i:
                current[:pos - i], current[pos - i:i] = [], current[:pos - i]
            else:
                current[-i:], current[-i - pos:-pos] = [], current[-i:]
            actions += 1

    return actions

