def min_actions_to_sort_train(n, cars):
    sorted_cars = sorted(cars)
    sorted_positions = {car: idx for idx, car in enumerate(sorted_cars)}
    current_positions = {car: idx for idx, car in enumerate(cars)}

    def get_distance(car):
        return abs(current_positions[car] - sorted_positions[car])

    moves = 0

    for _ in range(n):
        distances = [(get_distance(car), car) for car in cars]
        _, car = max(distances)

        if car != sorted_cars[-1]:
            moves += 1

            if sorted_positions[car] < current_positions[car]:
                cars.insert(0, cars.pop(current_positions[car]))
                current_positions = {car: idx for idx, car in enumerate(cars)}
            else:
                cars.append(cars.pop(current_positions[car]))
                current_positions = {car: idx for idx, car in enumerate(cars)}

            current_positions = {car: idx for idx, car in enumerate(cars)}

    return moves

